const { useEffect, useState } = React;

function App() {
  const [name, setName] = useState('');
  const [count, setCount] = useState(0);

  useEffect(() => {
    document.title = (name || '이름 없음') + ' · ' + count + '회';
    console.log('제목 동기화:', name, count);
  }, [name, count]);

  return (
    <main>
      <input value={name} onChange={(event) => setName(event.currentTarget.value)} placeholder="이름" />
      <button type="button" onClick={() => setCount(count + 1)}>증가 {count}</button>
    </main>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

